INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (4, 4896, 1, '{"name":"Davegulation 1: Campus Safety Standards","topic":"Campus Safety","requirements":"## Requirements\n\n- Implement emergency notification systems\n- Conduct safety drills quarterly\n- Appoint safety coordinators for each building\n\n## Compliance Deadlines\n\nInitial documentation: 6/1/2025\nFull implementation: 12/1/2025"}', '2025-01-15T05:00:00.000Z', 5, 'local', NULL, NULL);
INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (5, 4896, 2, '{"name":"Davegulation 1: Campus Safety Standards","topic":"Campus Safety","requirements":"## Requirements\n\n- Implement emergency notification systems\n- Conduct safety drills quarterly\n- Appoint safety coordinators for each building\n- **NEW**: Develop evacuation plans for all buildings\n\n## Compliance Deadlines\n\nInitial documentation: 6/1/2025\nFull implementation: 12/1/2025"}', '2025-02-20T05:00:00.000Z', 5, 'mcp', 'MCP-V2-REG4896', NULL);
INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (6, 4896, 3, '{"name":"Davegulation 1: Campus Safety Standards","topic":"Campus Safety","requirements":"## Requirements\n\n- Implement emergency notification systems\n- Conduct safety drills quarterly\n- Appoint safety coordinators for each building\n- Develop evacuation plans for all buildings\n- **NEW**: Install emergency communication stations\n\n## Compliance Deadlines\n\nInitial documentation: 6/1/2025\nFull implementation: 12/1/2025\n**UPDATED**: Final compliance review: 2/15/2026"}', '2025-03-10T04:00:00.000Z', 5, 'mcp', 'MCP-V3-REG4896', NULL);
INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (7, 4897, 1, '{"name":"Davegulation 2: Data Privacy Protocol","topic":"Data Privacy","requirements":"## Requirements\n\n- Implement data encryption for all PII\n- Obtain explicit consent for data collection\n- Establish data retention policies\n\n## Compliance Deadlines\n\nInitial assessment: 5/15/2025\nFull compliance: 11/30/2025"}', '2025-02-10T05:00:00.000Z', 5, 'local', NULL, NULL);
