INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (9, 4900, 1, '{"name":"Davegulation 5: Faculty Certification Requirements","topic":"Faculty Affairs","requirements":"## Requirements\n\n- Annual professional development hours\n- Subject matter expertise verification\n- Teaching methodology certification\n\n## Compliance Deadlines\n\nInitial certification: 9/1/2025\nFull faculty compliance: 3/15/2026"}', '2025-05-01T04:00:00.000Z', 5, 'local', NULL, NULL);
INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (10, 4900, 2, '{"name":"Davegulation 5: Faculty Certification Requirements","topic":"Faculty Affairs","requirements":"## Requirements\n\n- Annual professional development hours (40 hours minimum)\n- Subject matter expertise verification\n- Teaching methodology certification\n- **NEW**: Diversity and inclusion training\n\n## Compliance Deadlines\n\nInitial certification: 9/1/2025\nFull faculty compliance: 3/15/2026"}', '2025-06-15T04:00:00.000Z', 5, 'local', 'LOCAL-EDIT', NULL);
INSERT INTO regulation_versions (id, regulation_id, version_number, content, created_at, created_by, source, source_id, validation_status) VALUES (11, 4900, 3, '{"name":"Davegulation 5: Faculty Certification Requirements","topic":"Faculty Affairs","requirements":"## Requirements\n\n- Annual professional development hours (40 hours minimum)\n- Subject matter expertise verification (renewed every 3 years)\n- Teaching methodology certification\n- Diversity and inclusion training (annual requirement)\n- **NEW**: Digital teaching competency assessment\n\n## Compliance Deadlines\n\nInitial certification: 9/1/2025\nFull faculty compliance: 3/15/2026\n**UPDATED**: Digital competency deadline: 6/30/2026"}', '2025-07-10T04:00:00.000Z', 5, 'mcp', 'MCP-V3-REG4900', NULL);
